#!/usr/bin/env python3
from __future__ import annotations

import shutil
from pathlib import Path

PROJECT_ROOT = Path.home() / "Programs" / "SWARM_DRONES"
BACKUP_DIR = PROJECT_ROOT / "backups" / "point22_local_replanner"

FILES = {
    PROJECT_ROOT / "configs" / "safety" / "v1_swarm_local_replanner.yaml": 'replanner:\n  mode: dry_run\n  poll_interval_s: 0.5\n  decision_cooldown_s: 3.0\n  maximum_attempts_per_waypoint: 3\n\n  trigger_states:\n    - critical\n    - emergency_stop\n\n  minimum_side_clearance_m: 8.0\n  side_preference_margin_m: 1.0\n\n  temporary_waypoint:\n    forward_offset_m: 2.0\n    lateral_offset_m: 5.0\n    altitude_offset_m: 0.0\n\n  blocked_sides_action: abort_replan\n\n  event_log_csv: outputs/swarm/v1_three_drone_swarm/safety/{drone_id}_local_replanning_events.csv\n\ngeometry:\n  earth_radius_m: 6371000.0\n  minimum_target_vector_m: 0.25\n',
    PROJECT_ROOT / "swarm" / "safety" / "local_obstacle_replanner.py": '#!/usr/bin/env python3\nfrom __future__ import annotations\n\nimport csv\nimport math\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport yaml\n\n\nclass LocalObstacleReplanner:\n    def __init__(\n        self,\n        config_path: str | Path,\n        drone_id: str,\n    ) -> None:\n        config = yaml.safe_load(\n            Path(config_path).read_text()\n        )\n\n        replanner = config["replanner"]\n        geometry = config["geometry"]\n\n        self.drone_id = str(drone_id)\n        self.mode = str(replanner["mode"])\n        self.poll_interval_s = float(\n            replanner["poll_interval_s"]\n        )\n        self.decision_cooldown_s = float(\n            replanner["decision_cooldown_s"]\n        )\n        self.maximum_attempts_per_waypoint = int(\n            replanner[\n                "maximum_attempts_per_waypoint"\n            ]\n        )\n        self.trigger_states = {\n            str(value)\n            for value in replanner["trigger_states"]\n        }\n        self.minimum_side_clearance_m = float(\n            replanner[\n                "minimum_side_clearance_m"\n            ]\n        )\n        self.side_preference_margin_m = float(\n            replanner[\n                "side_preference_margin_m"\n            ]\n        )\n\n        temporary = replanner[\n            "temporary_waypoint"\n        ]\n\n        self.forward_offset_m = float(\n            temporary["forward_offset_m"]\n        )\n        self.lateral_offset_m = float(\n            temporary["lateral_offset_m"]\n        )\n        self.altitude_offset_m = float(\n            temporary["altitude_offset_m"]\n        )\n        self.blocked_sides_action = str(\n            replanner["blocked_sides_action"]\n        )\n        self.earth_radius_m = float(\n            geometry["earth_radius_m"]\n        )\n        self.minimum_target_vector_m = float(\n            geometry["minimum_target_vector_m"]\n        )\n\n        log_template = str(\n            replanner["event_log_csv"]\n        )\n        self.log_path = Path(\n            log_template.format(\n                drone_id=self.drone_id\n            )\n        )\n        self.log_path.parent.mkdir(\n            parents=True,\n            exist_ok=True,\n        )\n        self._initialize_log()\n\n    def _initialize_log(self) -> None:\n        if (\n            self.log_path.exists()\n            and self.log_path.stat().st_size\n        ):\n            return\n\n        with self.log_path.open(\n            "w",\n            newline="",\n        ) as file:\n            csv.writer(file).writerow([\n                "timestamp_utc",\n                "drone_id",\n                "safety_state",\n                "front_min_m",\n                "left_min_m",\n                "right_min_m",\n                "selected_side",\n                "temporary_north_m",\n                "temporary_east_m",\n                "temporary_altitude_m",\n                "mode",\n                "result",\n                "reason",\n            ])\n\n    @staticmethod\n    def _number(\n        value: Any,\n    ) -> float | None:\n        try:\n            number = float(value)\n        except (TypeError, ValueError):\n            return None\n\n        if not math.isfinite(number):\n            return None\n\n        return number\n\n    def position_to_local(\n        self,\n        home_latitude_deg: float,\n        home_longitude_deg: float,\n        latitude_deg: float,\n        longitude_deg: float,\n    ) -> tuple[float, float]:\n        north_m = (\n            math.radians(\n                latitude_deg\n                - home_latitude_deg\n            )\n            * self.earth_radius_m\n        )\n\n        east_m = (\n            math.radians(\n                longitude_deg\n                - home_longitude_deg\n            )\n            * self.earth_radius_m\n            * math.cos(\n                math.radians(\n                    home_latitude_deg\n                )\n            )\n        )\n\n        return north_m, east_m\n\n    def _direction_to_target(\n        self,\n        current_north_m: float,\n        current_east_m: float,\n        target_north_m: float,\n        target_east_m: float,\n        yaw_deg: float,\n    ) -> tuple[float, float]:\n        delta_north = (\n            target_north_m\n            - current_north_m\n        )\n        delta_east = (\n            target_east_m\n            - current_east_m\n        )\n        norm = math.hypot(\n            delta_north,\n            delta_east,\n        )\n\n        if norm >= self.minimum_target_vector_m:\n            return (\n                delta_north / norm,\n                delta_east / norm,\n            )\n\n        yaw_rad = math.radians(\n            yaw_deg\n        )\n\n        return (\n            math.cos(yaw_rad),\n            math.sin(yaw_rad),\n        )\n\n    def choose_side(\n        self,\n        left_min_m: float | None,\n        right_min_m: float | None,\n    ) -> tuple[str | None, str]:\n        left_clear = (\n            left_min_m is not None\n            and left_min_m\n            >= self.minimum_side_clearance_m\n        )\n        right_clear = (\n            right_min_m is not None\n            and right_min_m\n            >= self.minimum_side_clearance_m\n        )\n\n        if not left_clear and not right_clear:\n            return (\n                None,\n                "both_sides_below_minimum_clearance",\n            )\n\n        if left_clear and not right_clear:\n            return (\n                "left",\n                "left_is_only_clear_side",\n            )\n\n        if right_clear and not left_clear:\n            return (\n                "right",\n                "right_is_only_clear_side",\n            )\n\n        assert left_min_m is not None\n        assert right_min_m is not None\n\n        difference = (\n            left_min_m\n            - right_min_m\n        )\n\n        if (\n            abs(difference)\n            < self.side_preference_margin_m\n        ):\n            return (\n                "left",\n                "clearances_similar_left_tie_break",\n            )\n\n        if difference > 0:\n            return (\n                "left",\n                "left_has_greater_clearance",\n            )\n\n        return (\n            "right",\n            "right_has_greater_clearance",\n        )\n\n    def plan(\n        self,\n        *,\n        current_north_m: float,\n        current_east_m: float,\n        current_altitude_m: float,\n        target_north_m: float,\n        target_east_m: float,\n        yaw_deg: float,\n        front_min_m: float | None,\n        left_min_m: float | None,\n        right_min_m: float | None,\n        safety_state: str,\n    ) -> dict[str, Any]:\n        selected_side, reason = (\n            self.choose_side(\n                left_min_m,\n                right_min_m,\n            )\n        )\n\n        base = {\n            "safety_state": str(safety_state),\n            "front_min_m": self._number(\n                front_min_m\n            ),\n            "left_min_m": self._number(\n                left_min_m\n            ),\n            "right_min_m": self._number(\n                right_min_m\n            ),\n            "selected_side": selected_side,\n            "reason": reason,\n        }\n\n        if selected_side is None:\n            return {\n                **base,\n                "can_replan": False,\n                "result":\n                    self.blocked_sides_action,\n                "temporary_north_m": None,\n                "temporary_east_m": None,\n                "temporary_altitude_m": None,\n            }\n\n        forward_north, forward_east = (\n            self._direction_to_target(\n                current_north_m,\n                current_east_m,\n                target_north_m,\n                target_east_m,\n                yaw_deg,\n            )\n        )\n        left_north = -forward_east\n        left_east = forward_north\n        side_sign = (\n            1.0\n            if selected_side == "left"\n            else -1.0\n        )\n\n        temporary_north_m = (\n            current_north_m\n            + self.forward_offset_m\n            * forward_north\n            + side_sign\n            * self.lateral_offset_m\n            * left_north\n        )\n        temporary_east_m = (\n            current_east_m\n            + self.forward_offset_m\n            * forward_east\n            + side_sign\n            * self.lateral_offset_m\n            * left_east\n        )\n\n        return {\n            **base,\n            "can_replan": True,\n            "result": "plan_created",\n            "temporary_north_m":\n                temporary_north_m,\n            "temporary_east_m":\n                temporary_east_m,\n            "temporary_altitude_m": (\n                current_altitude_m\n                + self.altitude_offset_m\n            ),\n        }\n\n    def record_plan(\n        self,\n        plan: dict[str, Any],\n    ) -> None:\n        with self.log_path.open(\n            "a",\n            newline="",\n        ) as file:\n            csv.writer(file).writerow([\n                datetime.now(\n                    timezone.utc\n                ).isoformat(),\n                self.drone_id,\n                plan.get("safety_state"),\n                plan.get("front_min_m"),\n                plan.get("left_min_m"),\n                plan.get("right_min_m"),\n                plan.get("selected_side"),\n                plan.get(\n                    "temporary_north_m"\n                ),\n                plan.get(\n                    "temporary_east_m"\n                ),\n                plan.get(\n                    "temporary_altitude_m"\n                ),\n                self.mode,\n                plan.get("result"),\n                plan.get("reason"),\n            ])\n',
    PROJECT_ROOT / "tests" / "safety" / "test_local_obstacle_replanner.py": '#!/usr/bin/env python3\nfrom __future__ import annotations\n\nimport tempfile\nimport unittest\nfrom pathlib import Path\n\nimport yaml\n\nfrom swarm.safety.local_obstacle_replanner import (\n    LocalObstacleReplanner,\n)\n\n\nclass LocalObstacleReplannerTests(\n    unittest.TestCase\n):\n    def setUp(self) -> None:\n        self.temp_directory = (\n            tempfile.TemporaryDirectory()\n        )\n        root = Path(\n            self.temp_directory.name\n        )\n\n        config = {\n            "replanner": {\n                "mode": "dry_run",\n                "poll_interval_s": 0.5,\n                "decision_cooldown_s": 3.0,\n                "maximum_attempts_per_waypoint": 3,\n                "trigger_states": [\n                    "critical",\n                    "emergency_stop",\n                ],\n                "minimum_side_clearance_m": 8.0,\n                "side_preference_margin_m": 1.0,\n                "temporary_waypoint": {\n                    "forward_offset_m": 2.0,\n                    "lateral_offset_m": 5.0,\n                    "altitude_offset_m": 0.0,\n                },\n                "blocked_sides_action":\n                    "abort_replan",\n                "event_log_csv": str(\n                    root / "{drone_id}.csv"\n                ),\n            },\n            "geometry": {\n                "earth_radius_m": 6371000.0,\n                "minimum_target_vector_m": 0.25,\n            },\n        }\n\n        config_path = (\n            root / "replanner.yaml"\n        )\n        config_path.write_text(\n            yaml.safe_dump(\n                config,\n                sort_keys=False,\n            )\n        )\n\n        self.replanner = (\n            LocalObstacleReplanner(\n                config_path,\n                "drone_test",\n            )\n        )\n\n    def tearDown(self) -> None:\n        self.temp_directory.cleanup()\n\n    def test_left_side_selected(self) -> None:\n        plan = self.replanner.plan(\n            current_north_m=0.0,\n            current_east_m=0.0,\n            current_altitude_m=3.0,\n            target_north_m=10.0,\n            target_east_m=0.0,\n            yaw_deg=0.0,\n            front_min_m=4.0,\n            left_min_m=15.0,\n            right_min_m=6.0,\n            safety_state="emergency_stop",\n        )\n\n        self.assertTrue(\n            plan["can_replan"]\n        )\n        self.assertEqual(\n            plan["selected_side"],\n            "left",\n        )\n        self.assertAlmostEqual(\n            plan["temporary_north_m"],\n            2.0,\n        )\n        self.assertAlmostEqual(\n            plan["temporary_east_m"],\n            5.0,\n        )\n\n    def test_right_side_selected(self) -> None:\n        plan = self.replanner.plan(\n            current_north_m=0.0,\n            current_east_m=0.0,\n            current_altitude_m=3.0,\n            target_north_m=10.0,\n            target_east_m=0.0,\n            yaw_deg=0.0,\n            front_min_m=4.0,\n            left_min_m=9.0,\n            right_min_m=16.0,\n            safety_state="emergency_stop",\n        )\n\n        self.assertTrue(\n            plan["can_replan"]\n        )\n        self.assertEqual(\n            plan["selected_side"],\n            "right",\n        )\n        self.assertAlmostEqual(\n            plan["temporary_north_m"],\n            2.0,\n        )\n        self.assertAlmostEqual(\n            plan["temporary_east_m"],\n            -5.0,\n        )\n\n    def test_both_sides_blocked(self) -> None:\n        plan = self.replanner.plan(\n            current_north_m=0.0,\n            current_east_m=0.0,\n            current_altitude_m=3.0,\n            target_north_m=10.0,\n            target_east_m=0.0,\n            yaw_deg=0.0,\n            front_min_m=4.0,\n            left_min_m=7.0,\n            right_min_m=6.0,\n            safety_state="emergency_stop",\n        )\n\n        self.assertFalse(\n            plan["can_replan"]\n        )\n        self.assertEqual(\n            plan["result"],\n            "abort_replan",\n        )\n\n\nif __name__ == "__main__":\n    unittest.main()\n',
}


def backup(path: Path) -> None:
    if not path.exists():
        return

    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    destination = BACKUP_DIR / path.name
    counter = 1

    while destination.exists():
        destination = (
            BACKUP_DIR
            / f"{path.stem}_{counter}{path.suffix}"
        )
        counter += 1

    shutil.copy2(path, destination)


def main() -> None:
    if not PROJECT_ROOT.exists():
        raise SystemExit(
            f"Project root not found: {PROJECT_ROOT}"
        )

    for path, content in FILES.items():
        backup(path)
        path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )
        path.write_text(content)

    (
        PROJECT_ROOT
        / "swarm"
        / "safety"
        / "local_obstacle_replanner.py"
    ).chmod(0o755)

    (
        PROJECT_ROOT
        / "tests"
        / "safety"
        / "test_local_obstacle_replanner.py"
    ).chmod(0o755)

    print(
        "Point 22A local replanning "
        "decision layer installed."
    )
    print(
        "Mode: dry_run. No flight commands "
        "were added in this stage."
    )


if __name__ == "__main__":
    main()
